<template>
  <div>
    <div class="page-heading"><div><p class="eyebrow">采购财务闭环</p><h1>对账、发票与付款</h1><p>以采购订单为起点完成供应商对账、发票验真和付款审批，确保业务流与资金流一致。</p></div><el-button type="primary" @click="openCreate">{{createButton}}</el-button></div>
    <div class="process-strip"><span>1. 订单对账</span><i>→</i><span>2. 双方确认</span><i>→</i><span>3. 发票验真</span><i>→</i><span>4. 付款审批与支付</span></div>
    <el-tabs v-model="active" type="card" @tab-click="changeTab"><el-tab-pane label="对账单" name="reconciliations"/><el-tab-pane label="供应商发票" name="invoices"/><el-tab-pane label="付款计划" name="payments"/></el-tabs>
    <el-table :key="active" v-loading="loading" :data="items" class="data-table" :empty-text="`暂无${activeLabel}`">
      <template v-if="active==='reconciliations'"><el-table-column prop="reconciliation_no" label="对账单号" width="145"/><el-table-column prop="order_no" label="采购订单" width="140"/><el-table-column prop="supplier_name" label="供应商" min-width="170"/><el-table-column prop="amount" label="订单金额"/><el-table-column prop="adjustment_amount" label="调整金额"/><el-table-column label="应付金额"><template slot-scope="scope">¥ {{payable(scope.row)}}</template></el-table-column></template>
      <template v-else-if="active==='invoices'"><el-table-column prop="invoice_no" label="发票号码" width="160"/><el-table-column prop="supplier_name" label="供应商" min-width="180"/><el-table-column prop="amount" label="价税合计"/><el-table-column prop="tax_amount" label="税额"/><el-table-column prop="invoice_date" label="开票日期"/></template>
      <template v-else><el-table-column prop="payment_no" label="付款单号" width="145"/><el-table-column prop="invoice_no" label="发票号码" width="160"/><el-table-column prop="supplier_name" label="供应商" min-width="180"/><el-table-column prop="amount" label="付款金额"/><el-table-column prop="planned_date" label="计划付款日"/><el-table-column prop="paid_date" label="实际付款日"/></template>
      <el-table-column label="状态" width="100"><template slot-scope="scope"><el-tag :type="statusType(scope.row.status)">{{statusName(scope.row.status)}}</el-tag></template></el-table-column>
      <el-table-column label="操作" width="210" fixed="right"><template slot-scope="scope"><el-button v-if="active==='invoices'&&scope.row.attachment_name" type="text" @click="downloadInvoice(scope.row)">下载发票</el-button><el-button v-if="editable(scope.row)" type="text" @click="openEdit(scope.row)">编辑</el-button><el-button v-if="active==='reconciliations'&&scope.row.status==='draft'" type="text" @click="confirmReconciliation(scope.row)">确认</el-button><template v-if="active==='invoices'&&scope.row.status==='received'"><el-button type="text" @click="setStatus(scope.row,'verified')">验真</el-button><el-button type="text" class="danger-link" @click="setStatus(scope.row,'rejected')">驳回</el-button></template><el-button v-if="active==='payments'&&scope.row.status==='planned'" type="text" @click="setStatus(scope.row,'approved')">审批</el-button><el-button v-if="active==='payments'&&scope.row.status==='approved'" type="text" @click="setStatus(scope.row,'paid')">确认支付</el-button><el-button v-if="editable(scope.row)" type="text" class="danger-link" @click="remove(scope.row)">删除</el-button></template></el-table-column>
    </el-table>
    <div class="pagination-row"><span>共 {{pagination.total}} 条</span><el-pagination background layout="sizes, prev, pager, next" :page-sizes="[10,20,50]" :current-page="pagination.page" :page-size="pagination.page_size" :total="pagination.total" @current-change="changePage" @size-change="changeSize"/></div>

    <el-dialog :title="editingId?`编辑${activeLabel}`:createButton" :visible.sync="dialogVisible" width="620px" :close-on-click-modal="false"><el-form :model="form" label-width="110px">
      <template v-if="active==='reconciliations'"><el-form-item label="采购订单"><el-select v-model="form.order_id" filterable :disabled="!!editingId" style="width:100%" @change="selectOrder"><el-option v-for="order in orders" :key="order.id" :label="`${order.order_no} · ${order.supplier_name} · ¥${order.total_amount}`" :value="order.id"/></el-select></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="订单金额"><el-input-number v-model="form.amount" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="调整金额"><el-input-number v-model="form.adjustment_amount" :precision="2" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="调整说明"><el-input v-model="form.remark" type="textarea" :rows="3"/></el-form-item></template>
      <template v-else-if="active==='invoices'"><el-form-item label="已确认对账单"><el-select v-model="form.reconciliation_id" filterable :disabled="!!editingId" style="width:100%" @change="selectReconciliation"><el-option v-for="item in confirmedReconciliations" :key="item.id" :label="`${item.reconciliation_no} · ${item.supplier_name} · ¥${payable(item)}`" :value="item.id"/></el-select></el-form-item><el-form-item label="发票号码"><el-input v-model="form.invoice_no" :disabled="!!editingId"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="价税合计"><el-input-number v-model="form.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="税额"><el-input-number v-model="form.tax_amount" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="开票日期"><el-date-picker v-model="form.invoice_date" value-format="yyyy-MM-dd" type="date" style="width:100%"/></el-form-item></template>
      <template v-else><el-form-item label="已验真发票"><el-select v-model="form.invoice_id" filterable :disabled="!!editingId" style="width:100%" @change="selectInvoice"><el-option v-for="item in verifiedInvoices" :key="item.id" :label="`${item.invoice_no} · ${item.supplier_name} · ¥${item.amount}`" :value="item.id"/></el-select></el-form-item><el-form-item label="付款金额"><el-input-number v-model="form.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="计划付款日"><el-date-picker v-model="form.planned_date" value-format="yyyy-MM-dd" type="date" style="width:100%"/></el-form-item></template>
    </el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog>
  </div>
</template>
<script>
import { api, createFlowItem, deleteFlowItem, fetchFlowItems, fetchOrders, runFlowAction, updateFlowItem, updateFlowStatus } from "../api/client";
const forms={reconciliations:()=>({order_id:"",amount:0,adjustment_amount:0,remark:""}),invoices:()=>({invoice_no:"",reconciliation_id:"",amount:0,tax_amount:0,invoice_date:null}),payments:()=>({invoice_id:"",amount:0,planned_date:null})};
export default {data:()=>({active:"reconciliations",items:[],orders:[],reconciliations:[],invoices:[],loading:false,saving:false,dialogVisible:false,editingId:"",form:forms.reconciliations(),pagination:{page:1,page_size:10,total:0}}),computed:{activeLabel(){return {reconciliations:"对账单",invoices:"供应商发票",payments:"付款计划"}[this.active];},createButton(){return {reconciliations:"新建对账单",invoices:"登记发票",payments:"新建付款计划"}[this.active];},confirmedReconciliations(){return this.reconciliations.filter(item=>item.status==="confirmed");},verifiedInvoices(){return this.invoices.filter(item=>item.status==="verified");}},async created(){await Promise.all([this.load(),this.loadOptions()]);},methods:{async downloadInvoice(row){try{const r=await api.get(`/invoices/${row.id}/file`,{responseType:"blob"});const u=URL.createObjectURL(r.data),a=document.createElement("a");a.href=u;a.download=row.attachment_name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(e){this.$message.error(e.response?.data?.detail||"发票下载失败");}},statusName(v){return {draft:"草稿",confirmed:"已确认",received:"待验真",verified:"已验真",rejected:"已驳回",planned:"待审批",approved:"已批准",paid:"已支付"}[v]||v;},statusType(v){return {draft:"info",confirmed:"success",received:"warning",verified:"success",rejected:"danger",planned:"warning",approved:"success",paid:"success"}[v]||"";},editable(item){if(this.active==="invoices"&&item.attachment_name)return false;return item.status==="draft"||item.status==="received"||item.status==="planned";},payable(item){return (Number(item.amount||0)+Number(item.adjustment_amount||0)).toFixed(2);},async load(){this.loading=true;try{const result=await fetchFlowItems(this.active,{page:this.pagination.page,page_size:this.pagination.page_size});this.items=result.items;this.pagination.total=result.total;}catch(_){this.$message.error(`${this.activeLabel}加载失败`);}finally{this.loading=false;}},async loadOptions(){const [orders,reconciliations,invoices]=await Promise.all([fetchOrders({ page: 1, page_size: 100, unfiltered: true }),fetchFlowItems("reconciliations",{ page: 1, page_size: 100, unfiltered: true }),fetchFlowItems("invoices",{ page: 1, page_size: 100, unfiltered: true })]);this.orders=orders.items;this.reconciliations=reconciliations.items;this.invoices=invoices.items;},changeTab(){this.pagination.page=1;this.load();this.loadOptions();},changePage(page){this.pagination.page=page;this.load();},changeSize(size){this.pagination.page_size=size;this.pagination.page=1;this.load();},openCreate(){this.editingId="";this.form=forms[this.active]();this.dialogVisible=true;},openEdit(item){this.editingId=item.id;this.form={...item,amount:Number(item.amount),adjustment_amount:Number(item.adjustment_amount),tax_amount:Number(item.tax_amount)};this.dialogVisible=true;},selectOrder(id){const order=this.orders.find(item=>item.id===id);if(order)this.form.amount=Number(order.total_amount);},selectReconciliation(id){const item=this.reconciliations.find(row=>row.id===id);if(item)this.form.amount=Number(this.payable(item));},selectInvoice(id){const item=this.invoices.find(row=>row.id===id);if(item)this.form.amount=Number(item.amount);},async save(){if((this.active==="reconciliations"&&!this.form.order_id)||(this.active==="invoices"&&(!this.form.reconciliation_id||!this.form.invoice_no))||(this.active==="payments"&&!this.form.invoice_id))return this.$message.warning("请完整填写关联单据");this.saving=true;try{if(this.editingId){const payload=this.active==="reconciliations"?{amount:this.form.amount,adjustment_amount:this.form.adjustment_amount,remark:this.form.remark}:this.active==="invoices"?{amount:this.form.amount,tax_amount:this.form.tax_amount,invoice_date:this.form.invoice_date}:{amount:this.form.amount,planned_date:this.form.planned_date};await updateFlowItem(this.active,this.editingId,payload);}else await createFlowItem(this.active,this.form);this.$message.success(`${this.activeLabel}已保存`);this.dialogVisible=false;await Promise.all([this.load(),this.loadOptions()]);}catch(error){this.$message.error(error.response&&error.response.data&&error.response.data.detail||"保存失败");}finally{this.saving=false;}},async confirmReconciliation(item){try{await this.$confirm(`确认对账单 ${item.reconciliation_no}？`,"确认对账",{type:"warning"});await runFlowAction("reconciliations",item.id,"confirm");this.$message.success("对账单已确认");await Promise.all([this.load(),this.loadOptions()]);}catch(error){if(error!=="cancel")this.$message.error("确认失败");}},async setStatus(item,status){try{await updateFlowStatus(this.active,item.id,status);this.$message.success("状态已更新");await Promise.all([this.load(),this.loadOptions()]);}catch(error){this.$message.error("状态更新失败");}},async remove(item){try{await this.$confirm("确定删除当前记录吗？","删除确认",{type:"warning"});await deleteFlowItem(this.active,item.id);this.$message.success("已删除");await this.load();}catch(error){if(error!=="cancel")this.$message.error("删除失败");}}}};
</script>
